sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // Exit if the form is loading or the value hasn't changed
    if (isLoading || newValue === oldValue) {
        return;
    }

    // Parse the new value as an integer
    var points = parseInt(newValue, 10);

    // Check if the value exceeds the maximum allowed value
    if (points > 100) {
        // Reset the value to the maximum allowed value
        g_form.setValue('points', 100);

        // Display an error message
        g_form.showFieldMsg('points', 'The maximum value for points is 100. The value has been reset to 100.', 'error');
    }
}
